-- 90_VERIFY.sql — DMF0040 적용 확인 [20260827]
SELECT OBJECT_NAME, OBJECT_TYPE, STATUS FROM ALL_OBJECTS WHERE OWNER='SCM_MGR' AND OBJECT_NAME IN ('PKG_DMF0040', 'PKG_DMF0007');
SELECT COUNT(*) AS INVALID_CNT FROM ALL_OBJECTS WHERE OWNER='SCM_MGR' AND STATUS='INVALID' AND OBJECT_NAME IN ('PKG_DMF0040', 'PKG_DMF0007');
SELECT 'SCM_ADM_PROGRAM' T, COUNT(*) CNT FROM SCM_MGR.SCM_ADM_PROGRAM WHERE PROGRAM_ID LIKE 'DMF0040%';  -- 기대 1
SELECT 'SCM_ADM_MNU_M' T, COUNT(*) CNT FROM SCM_MGR.SCM_ADM_MNU_M WHERE MNU_ID LIKE 'DMF0040%';  -- 기대 1
SELECT 'SCM_ADM_USER_GR_MNU_MPG_M' T, COUNT(*) CNT FROM SCM_MGR.SCM_ADM_USER_GR_MNU_MPG_M WHERE MNU_ID LIKE 'DMF0040%';  -- 기대 4
SELECT 'SCM_ADM_MNU_BTN_MPG_M' T, COUNT(*) CNT FROM SCM_MGR.SCM_ADM_MNU_BTN_MPG_M WHERE MNU_ID LIKE 'DMF0040%';  -- 기대 5
SELECT 'SCM_ADM_USER_GR_MNU_BTN_MPG_M' T, COUNT(*) CNT FROM SCM_MGR.SCM_ADM_USER_GR_MNU_BTN_MPG_M WHERE MNU_ID LIKE 'DMF0040%';  -- 기대 20
SELECT 'SCM_ADM_API_M' T, COUNT(*) CNT FROM SCM_MGR.SCM_ADM_API_M WHERE API_ID LIKE 'DMF0040%';  -- 기대 5
SELECT 'SCM_MST_SHEET_COLUMNS/Mkt Fcst Waterfall' T, COUNT(*) CNT FROM SCM_MGR.SCM_MST_SHEET_COLUMNS WHERE PROGRAM_ID='DMF0040' AND SHEET_NAME='Mkt Fcst Waterfall';  -- 기대 48
SELECT 'SCM_MST_SHEET_MEASURE/Mkt Fcst Waterfall' T, COUNT(*) CNT FROM SCM_MGR.SCM_MST_SHEET_MEASURE WHERE PROGRAM_ID='DMF0040' AND SHEET_NAME='Mkt Fcst Waterfall';  -- 기대 3
SELECT COUNT(*) AS GTT_CNT FROM ALL_TABLES WHERE OWNER='SCM_MGR' AND TEMPORARY='Y' AND TABLE_NAME IN ('GT_DM40_ITEM_INPUT', 'GT_DM40_ITEM_SINGLE', 'GT_DM40_ITEM_SINGLE_A', 'GT_DM40_ITEM_SINGLE_B', 'GT_DM40_ITEM_SINGLE_ORI', 'GT_DM40_PROJECT_INPUT');  -- 기대 6

-- ── V11~V13 조용한-실패 게이트 (hook #148 cloud-deploy-silent-failure-gates, 2026-08-28 — §4.7-B V11 미구현 재발 정정) ──
-- V11 메뉴 행 실존 + UNIT_TP_CD='D'/USE_YN='Y' (기대 1행) — 부재 시 SCM_ADM_USER_MNU_EDIT_AUTH_V INNER JOIN 으로 오류 없이 0행
SELECT 'V11-MNU' G, MNU_ID, UNIT_TP_CD, USE_YN FROM SCM_MGR.SCM_ADM_MNU_M WHERE MNU_ID='DMF0040';
-- V11-B 테스트 계정 권한 뷰 반환 행 (기대 ≥1, 조회 Division 포함) — <TEST_USER> 를 실제 로그인 ID 로
SELECT 'V11-AUTH' G, UNIT_ID, EDIT_YN FROM SCM_MGR.SCM_ADM_USER_MNU_EDIT_AUTH_V WHERE USER_ID='<TEST_USER>' AND MNU_ID='DMF0040' ORDER BY 2;
-- V12 앱 계정 EXECUTE + private synonym (기대: 객체별 SCMP_APP 각 1행 — 없으면 40_GRANT_SYNONYM.sql) — 부재 시 화면 "SQL ERROR"(PLS-00201)
SELECT 'V12-GRANT' G, TABLE_NAME, GRANTEE FROM ALL_TAB_PRIVS WHERE TABLE_SCHEMA='SCM_MGR' AND PRIVILEGE='EXECUTE' AND GRANTEE='SCMP_APP' AND TABLE_NAME IN ('PKG_DMF0040','PKG_DMF0007','FN_MULTY_TIME','PR_SCM_SYS_LOG_BATCH','DMF0002_GET_TITLESET_POPUP','DMF0040_GET_SPREAD_TITLE','SCM0002_SET_TITLESET_POPUP') ORDER BY 2;
SELECT 'V12-SYN' G, SYNONYM_NAME FROM ALL_SYNONYMS WHERE OWNER='SCMP_APP' AND TABLE_OWNER='SCM_MGR' AND SYNONYM_NAME IN ('PKG_DMF0040','PKG_DMF0007','FN_MULTY_TIME','PR_SCM_SYS_LOG_BATCH','DMF0002_GET_TITLESET_POPUP','DMF0040_GET_SPREAD_TITLE','SCM0002_SET_TITLESET_POPUP') ORDER BY 2;
-- V13 PKG 본문이 V_PROGRAM_ID 로 읽는 종속 PROGRAM_ID 전부의 시트 메타 (기대: 각 PROGRAM_ID 행 > 0 — 사내 값은 22/22A 파일 주석)
SELECT 'V13-META' G, PROGRAM_ID, 'COLUMNS' T, COUNT(*) CNT FROM SCM_MGR.SCM_MST_SHEET_COLUMNS WHERE PROGRAM_ID IN ('DMF0040') GROUP BY PROGRAM_ID
UNION ALL SELECT 'V13-META', PROGRAM_ID, 'MEASURE', COUNT(*) FROM SCM_MGR.SCM_MST_SHEET_MEASURE WHERE PROGRAM_ID IN ('DMF0040') GROUP BY PROGRAM_ID ORDER BY 2,3;
